import json, sys

def reconcile(payload: dict) -> dict:
    gw = {tx['reference']: (tx['amount_cents'], tx['status']) for tx in payload.get('gateway', [])}
    ld = {tx['reference']: (tx['amount_cents'], tx['status']) for tx in payload.get('ledger', [])}
    mismatches = sorted(ref for ref in (set(gw) | set(ld)) if gw.get(ref) != ld.get(ref))
    return {'mismatches': mismatches}

if __name__ == '__main__':
    print(json.dumps(reconcile(json.loads(sys.stdin.read()))))
